// R9 (acceptance check 4): the browser's first AudioContext of a session takes 45 ms on a warm machine and 300 ms and more when the audio service and the sound device have to start; it was built inside the click
// on "Enable Sound & Start", which made the click one long task (292-389 ms on both shells). It is built here instead, in the page's first task and before the first paint, while the placement files download
// (the download is started first and goes on while the context is built). The context stays suspended until the click.
const placementFetches = PLACEMENT_FILES.map(f => fetch('/data/' + f).then(r => r.json()));
let preAudio = null;
try { preAudio = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { preAudio = null; }
const responses = await Promise.all(placementFetches);

function initAudio() {
  audioCtx = preAudio || new (window.AudioContext || window.webkitAudioContext)();   // R9: built before the first paint (see above); only a browser that refused that builds it here
  preAudio = null;
  if (audioCtx.state === 'suspended') audioCtx.resume().catch(() => {});   // a context built before the click starts suspended; the click is the user action that lets it run
